#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9

PHASE="all"
PROJECT="all"
ASSUME_YES="${COURSE_ASSUME_YES:-0}"
RUN_MODE="${COURSE_RUN_MODE:-smoke}"
RUN_VERSION="${COURSE_VERSION:-baseline}"

usage() {
  cat <<'EOF'
Usage:
  bash scripts/install_and_run_p1_p4.sh
  bash scripts/install_and_run_p1_p4.sh --phase setup
  bash scripts/install_and_run_p1_p4.sh --phase golden|rtl|ppa --project p1|p2|p3|p4|all

Options:
  --phase NAME       all (default), setup, golden, rtl, or ppa
  --project NAME     p1, p2, p3, p4, or all (default)
  --jobs N           parallel build jobs (default: detected CPU count)
  --skip-openroad    skip the native OpenROAD/SKY130 installation
  --with-ppa         run PPA without asking after a complete installation
  COURSE_RUN_MODE    smoke (default), full, or perf; set by the progress API
  COURSE_VERSION     source/evidence version label (safe filename characters)
  --yes              accept installation prompts (for a disposable clean-room machine)
  -h, --help         show this help

Typical optimization loop:
  bash scripts/install_and_run_p1_p4.sh --phase rtl --project p2
  bash scripts/install_and_run_p1_p4.sh --phase ppa --project p2
EOF
}

while (( $# )); do
  case "$1" in
    --phase)
      [[ $# -ge 2 ]] || { warn "--phase needs a value"; exit 2; }
      PHASE="$2"
      shift 2
      ;;
    --project)
      [[ $# -ge 2 ]] || { warn "--project needs a value"; exit 2; }
      PROJECT="$2"
      shift 2
      ;;
    --jobs)
      [[ $# -ge 2 ]] || { warn "--jobs needs a value"; exit 2; }
      COURSE_JOBS="$2"
      shift 2
      ;;
    --skip-openroad)
      COURSE_SKIP_OPENROAD=1
      shift
      ;;
    --with-ppa)
      COURSE_RUN_PPA=1
      shift
      ;;
    --yes)
      ASSUME_YES=1
      shift
      ;;
    -h|--help)
      usage
      exit 0
      ;;
    *)
      warn "unknown argument: $1"
      usage
      exit 2
      ;;
  esac
done

case "$PHASE" in
  all|setup|golden|rtl|ppa) ;;
  *) warn "--phase must be all, setup, golden, rtl, or ppa"; exit 2 ;;
esac
case "$PROJECT" in
  all|p1|p2|p3|p4) ;;
  *) warn "--project must be all, p1, p2, p3, or p4"; exit 2 ;;
esac
case "$ASSUME_YES" in
  0|1) ;;
  *) warn "COURSE_ASSUME_YES must be 0 or 1"; exit 2 ;;
esac
case "$RUN_MODE" in
  smoke|full|perf) ;;
  *) warn "COURSE_RUN_MODE must be smoke, full, or perf"; exit 2 ;;
esac
if ! [[ "$RUN_VERSION" =~ ^[A-Za-z0-9._-]{1,64}$ ]]; then
  warn "COURSE_VERSION must use 1-64 letters, digits, dots, underscores, or hyphens"
  exit 2
fi
if [[ -n "${COURSE_JOBS:-}" ]] && ! [[ "$COURSE_JOBS" =~ ^[1-9][0-9]*$ ]]; then
  warn "--jobs must be a positive integer"
  exit 2
fi

if [[ "$ASSUME_YES" == "1" ]]; then
  confirm() {
    note "$1 [automatically accepted by --yes]"
    return 0
  }
  pause() {
    note "$1 [continued by --yes]"
  }
fi

COURSE_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
STATE_DIR="${COURSE_ROOT}/build/setup-state"
LOG_DIR="${COURSE_ROOT}/build/setup-logs"
TOOLS_PREFIX="${COURSE_ROOT}/build/tools"
VENV_DIR="${COURSE_ROOT}/.venv"
JOBS="${COURSE_JOBS:-$(getconf _NPROCESSORS_ONLN 2>/dev/null || printf '4')}"
RUN_OPENROAD=0
SUDO=()
if (( EUID != 0 )) && command -v sudo >/dev/null 2>&1; then
  SUDO=(sudo)
fi

mkdir -p "$STATE_DIR" "$LOG_DIR" "$TOOLS_PREFIX"
cd "$COURSE_ROOT"

done_before() { [[ -f "${STATE_DIR}/$1.done" ]]; }
mark_done() { printf '%s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" > "${STATE_DIR}/$1.done"; }
run_logged() {
  local name="$1"
  shift
  say "日志：build/setup-logs/${name}.log"
  if "$@" > >(tee "${LOG_DIR}/${name}.log") 2>&1; then
    printf '  %s✓ passed%s %s\n' "$GREEN" "$RESET" "$name"
  else
    printf '  %s✗ failed%s %s\n' "$RED" "$RESET" "$name" >&2
    printf '  查看日志：%s\n' "${LOG_DIR}/${name}.log" >&2
    return 1
  fi
}
activate_course_env() {
  export PATH="${TOOLS_PREFIX}/bin:${PATH}"
  if [[ -f "${COURSE_ROOT}/third_party/src/openroad-flow-scripts/env.sh" ]]; then
    # ORFS env.sh 若从 Windows 拷来可能带 CRLF；先去掉再 source，失败也不阻断 golden/rtl
    set +u
    # shellcheck disable=SC1091
    sed -i 's/\r$//' "${COURSE_ROOT}/third_party/src/openroad-flow-scripts/env.sh" 2>/dev/null || true
    # shellcheck disable=SC1091
    source "${COURSE_ROOT}/third_party/src/openroad-flow-scripts/env.sh" || warn "ORFS env.sh source 失败（golden/rtl 通常仍可继续）"
    set -u
  fi
  if [[ ! -f "${VENV_DIR}/bin/activate" ]]; then
    warn "${VENV_DIR}/bin/activate is missing. Run this script once with --phase setup."
    exit 2
  fi
  # shellcheck disable=SC1091
  source "${VENV_DIR}/bin/activate"
}

selected_projects() {
  if [[ "$PROJECT" == "all" ]]; then
    printf '%s\n' p1 p2 p3 p4
  else
    printf '%s\n' "$PROJECT"
  fi
}

run_golden() {
  local design="$1"
  case "$design" in
    p1) run_logged p1-golden python -m pytest -q tests/test_dsa.py tests/test_addressing.py tests/test_attention.py ;;
    p2) run_logged p2-golden python -m pytest -q tests/test_addressing.py tests/test_attention.py ;;
    p3) run_logged p3-golden python -m pytest -q tests/test_moe.py ;;
    p4) run_logged p4-golden python -m pytest -q tests/test_deepseek_v32.py ;;
  esac
}

run_rtl() {
  local design="$1"
  run_logged "${design}-rtl" python scripts/run_rtl.py --name "$design"
  if [[ "$RUN_MODE" == "perf" ]]; then
    python scripts/record_metric_jsonl.py \
      --log "${LOG_DIR}/${design}-rtl.log" \
      --output "${COURSE_ROOT}/build/evidence/${RUN_VERSION}/${design}/run-status.jsonl"
  fi
}

run_profile_contracts() {
  [[ "$RUN_MODE" == "smoke" ]] && return 0
  run_logged "${RUN_MODE}-${RUN_VERSION}-contracts" python -m pytest -q \
    tests/test_operator_manifest.py \
    tests/test_rtl_oracle.py \
    tests/test_litex_contract.py \
    tests/test_nano_image.py \
    tests/test_operator_mutations.py \
    tests/test_optimization.py
}

run_shared_rtl_contracts() {
  [[ "$RUN_MODE" != "full" ]] && return 0
  local shared_test
  for shared_test in \
    litex_descriptor litex_dispatcher dma_adapter sram_seam \
    numeric_cores numeric_contract stable_topk online_softmax softmax_merge \
    silu_lut fixed_divider p1_numeric_b0 p1_litex_b0 p1_trace_b0 \
    p2_numeric_b0 p3_numeric_b0 \
    split_merge_reorder int8_dot_serial p2_litex_b0 p3_expert_row_b0 \
    p3_litex_b0 p3_trace_b0 litex_native_dma_bridge; do
    if [[ "$shared_test" == "p3_litex_b0" ]]; then
      COURSE_FULL_P3_CASES=1 COURSE_P3_SEED_CASES=1 \
        run_logged "shared-${shared_test}" python scripts/run_rtl.py --name "$shared_test"
    else
      run_logged "shared-${shared_test}" python scripts/run_rtl.py --name "$shared_test"
    fi
  done
}

prepare_case_evidence() {
  [[ "$RUN_MODE" != "full" ]] && return 0
  local operator
  for operator in p1 p2 p3; do
    rm -f "${COURSE_ROOT}/build/evidence/fragments/${operator}-"*.jsonl
    rm -f "${COURSE_ROOT}/build/evidence/${RUN_VERSION}/${operator}/cases.jsonl"
    rm -f "${COURSE_ROOT}/build/evidence/${RUN_VERSION}/${operator}/coverage.json"
    rm -f "${COURSE_ROOT}/build/evidence/${RUN_VERSION}/${operator}/full.pass.json"
  done
}

run_formal() {
  local design="$1"
  [[ "$RUN_MODE" != "full" || "$design" == "p4" ]] && return 0
  command -v sby >/dev/null 2>&1 || {
    warn "sby is unavailable; full mode requires SymbiYosys."
    exit 2
  }
  run_logged "${design}-formal" bash -lc \
    "cd '${COURSE_ROOT}/shared/formal' && sby -f '${design}_protocol.sby'"
  if [[ "$design" == "p1" ]]; then
    run_logged "p1-vertical-formal" bash -lc \
      "cd '${COURSE_ROOT}/shared/formal' && sby -f p1_vertical_protocol.sby"
  fi
  if [[ "$design" == "p2" ]]; then
    run_logged "p2-vertical-formal" bash -lc \
      "cd '${COURSE_ROOT}/shared/formal' && sby -f p2_vertical_protocol.sby"
  fi
  if [[ "$design" == "p3" ]]; then
    run_logged "p3-vertical-formal" bash -lc \
      "cd '${COURSE_ROOT}/shared/formal' && sby -f p3_vertical_protocol.sby"
  fi
}

case_evidence_path() {
  printf '%s/build/evidence/%s/%s/cases.jsonl' "$COURSE_ROOT" "$RUN_VERSION" "$1"
}

full_evidence_stamp() {
  printf '%s/build/evidence/%s/%s/full.pass.json' "$COURSE_ROOT" "$RUN_VERSION" "$1"
}

run_case_evidence_gate() {
  local design="$1"
  [[ "$design" == "p4" || "$RUN_MODE" == "smoke" ]] && return 0
  local evidence stamp
  evidence="$(case_evidence_path "$design")"
  stamp="$(full_evidence_stamp "$design")"
  if [[ "$RUN_MODE" == "perf" ]]; then
    [[ -f "$stamp" ]] || {
      warn "perf requires a prior complete full evidence stamp: $stamp"
      exit 2
    }
    return 0
  fi
  run_logged "${design}-assemble-case-evidence" python scripts/assemble_case_evidence.py \
    --operator "$design" --version "$RUN_VERSION"
  run_logged "${design}-case-evidence" python scripts/validate_case_evidence.py \
    "$evidence" --operator "$design" --require-seeds --stamp "$stamp"
}

run_ppa() {
  local design="$1"
  local orfs_root="${COURSE_ROOT}/third_party/src/openroad-flow-scripts"
  [[ -f "${orfs_root}/flow/Makefile" ]] || {
    warn "OpenROAD-flow-scripts is missing. Run --phase setup and install OpenROAD first."
    exit 2
  }
  command -v openroad >/dev/null 2>&1 || {
    warn "openroad is not on PATH. Check build/course-env.sh or rerun --phase setup."
    exit 2
  }
  run_logged "${design}-ppa" make -C "${orfs_root}/flow" \
    "DESIGN_CONFIG=${COURSE_ROOT}/ppa/designs/${design}/config.mk" \
    "COURSE_ROOT=${COURSE_ROOT}"
}

write_course_env() {
  local orfs_root="${COURSE_ROOT}/third_party/src/openroad-flow-scripts"
  {
    printf 'source %q\n' "${VENV_DIR}/bin/activate"
    printf 'export PATH=%q:$PATH\n' "${TOOLS_PREFIX}/bin"
    printf '[[ -f %q ]] && source %q\n' "${orfs_root}/env.sh" "${orfs_root}/env.sh"
  } > "${COURSE_ROOT}/build/course-env.sh"
}

# Fast, non-interactive path for the inner optimization loop. It deliberately
# never installs packages or downloads sources.
if [[ "$PHASE" == "golden" || "$PHASE" == "rtl" || "$PHASE" == "ppa" ]]; then
  [[ "$(uname -s)" == "Linux" ]] || {
    warn "Project runs are supported on Linux only. On Windows, use Ubuntu/WSL2."
    exit 2
  }
  activate_course_env
  mapfile -t PROJECTS < <(selected_projects)
  case "$PHASE" in
    golden)
      run_logged structure python scripts/lint_structure.py
      for design in "${PROJECTS[@]}"; do run_golden "$design"; done
      ;;
    rtl)
      run_profile_contracts
      prepare_case_evidence
      run_shared_rtl_contracts
      for design in "${PROJECTS[@]}"; do
        run_rtl "$design"
        run_formal "$design"
        run_case_evidence_gate "$design"
      done
      ;;
    ppa)
      for design in "${PROJECTS[@]}"; do run_ppa "$design"; done
      ;;
  esac
  say "Completed phase=${PHASE}, project=${PROJECT}, mode=${RUN_MODE}, version=${RUN_VERSION}. Logs: ${LOG_DIR}"
  exit 0
fi

if [[ "$PHASE" == "setup" ]]; then
  TOTAL_STAGES=6
fi

banner "Open SoC AI Labs · install tools and run P1–P4"
note "No account, browser login, license server, cloud credential, or model weight is needed."
note "Re-running is safe: completed stages are recorded under build/setup-state/."

stage "Linux and hardware preflight"
if [[ "$(uname -s)" != "Linux" ]]; then
  warn "This script supports Linux only. On Windows, run it inside Ubuntu/WSL2."
  exit 2
fi
if ! command -v apt-get >/dev/null 2>&1; then
  warn "Only Ubuntu/Debian with apt is supported by this installer."
  exit 2
fi
if [[ -r /etc/os-release ]]; then
  # shellcheck disable=SC1091
  source /etc/os-release
  say "Detected: ${PRETTY_NAME:-Linux}"
  if [[ "${ID:-}" != "ubuntu" || "${VERSION_ID:-}" != "24.04" ]]; then
    warn "The complete OpenROAD path is qualified only on Ubuntu 24.04."
    warn "Other Debian/Ubuntu releases may run P1–P4 RTL with COURSE_SKIP_OPENROAD=1."
  fi
fi
if (( EUID == 0 )) && [[ "${COURSE_SKIP_OPENROAD:-0}" != "1" ]]; then
  warn "The OpenROAD stage must be launched by a normal user with sudo, not by a root login."
fi
free_kib=$(df -Pk "$COURSE_ROOT" | awk 'NR==2 {print $4}')
free_gib=$((free_kib / 1024 / 1024))
say "Workspace: ${COURSE_ROOT}"
say "CPU jobs: ${JOBS}; free disk: approximately ${free_gib} GiB"
if (( free_gib < 20 )); then
  warn "P1–P4 RTL needs less space, but a local OpenROAD build normally needs much more."
fi
python_version="$(python3 -c 'import sys; print(f"{sys.version_info.major}.{sys.version_info.minor}")' 2>/dev/null || true)"
if [[ -n "$python_version" ]] && ! python3 -c 'import sys; raise SystemExit(sys.version_info < (3, 11))'; then
  warn "Python ${python_version} is too old; the complete course installer targets Ubuntu 24.04."
  exit 2
fi
pause "Preflight complete. Press Enter to install the free/open-source packages."

stage "APT base tools"
if done_before apt; then
  say "Already completed; remove build/setup-state/apt.done to force this stage."
else
  if (( EUID == 0 )); then
    say "Running as root; sudo is not needed."
  elif (( ${#SUDO[@]} )); then
    if "${SUDO[@]}" -n true 2>/dev/null; then
      step "Non-interactive sudo authorization is already available."
    else
      step "sudo will ask for the local Linux account password. No credential is saved."
      "${SUDO[@]}" -v
    fi
  else
    warn "sudo is required to install APT packages."
    exit 2
  fi
  confirm "Install compilers, Python, Verilator, Yosys, solvers, GTKWave, and Podman with apt?" || exit 2
  run_logged apt-update "${SUDO[@]}" apt-get update
  run_logged apt-install "${SUDO[@]}" env DEBIAN_FRONTEND=noninteractive apt-get install -y --no-install-recommends \
    bash build-essential ca-certificates clang cmake curl git gtkwave make ninja-build podman \
    binutils-riscv64-unknown-elf gcc-riscv64-unknown-elf \
    python3 python3-pip python3-venv verilator yosys z3 \
    bison flex gawk graphviz libffi-dev libfl-dev libreadline-dev pkg-config tcl-dev
  # ORFS setup checks for a docker-compatible command. This small Podman
  # wrapper avoids adding Docker's external APT repository and daemon.
  if apt-cache show podman-docker >/dev/null 2>&1; then
    run_logged apt-podman-docker "${SUDO[@]}" env DEBIAN_FRONTEND=noninteractive apt-get install -y --no-install-recommends podman-docker
  else
    warn "podman-docker is unavailable; ORFS setup may install Docker Engine as a compatibility dependency."
  fi
  if apt-cache show boolector >/dev/null 2>&1; then
    run_logged apt-boolector "${SUDO[@]}" env DEBIAN_FRONTEND=noninteractive apt-get install -y --no-install-recommends boolector
  else
    warn "boolector is not present in this distribution; Z3 remains available."
    SKIPPED+=("Boolector package; formal smoke may need a supported Ubuntu/Debian release")
  fi
  mark_done apt
fi

stage "Pinned Python environment"
if done_before python; then
  say "Already completed; using ${VENV_DIR}."
else
  if ! python3 -c 'import sys; raise SystemExit(sys.version_info < (3, 11))'; then
    warn "The installed Python is older than 3.11. The complete course installer targets Ubuntu 24.04."
    exit 2
  fi
  python3 -m venv "$VENV_DIR"
  run_logged python-bootstrap "${VENV_DIR}/bin/python" -m pip install --upgrade -r requirements-bootstrap-lock.txt
  run_logged python-lock "${VENV_DIR}/bin/python" -m pip install -r requirements-lock.txt
  run_logged python-course "${VENV_DIR}/bin/python" -m pip install --no-build-isolation --no-deps -e .
  mark_done python
fi
activate_course_env
python -c 'import sys; print("  Python:", sys.executable, sys.version.split()[0])'

stage "Version-locked source downloads"
if done_before sources; then
  say "Already completed; sources are under third_party/src/."
else
  say "This anonymously downloads Ibex, ORFS, SymbiYosys, and OpenRAM at locked commits."
  say "DeepSeek and FlashMLA are reference-only; full model weights are never downloaded."
  confirm "Fetch the locked open-source repositories now?" || exit 2
  run_logged source-fetch python scripts/fetch_locked_sources.py
  run_logged source-locks python scripts/verify_source_locks.py
  mark_done sources
fi

stage "SymbiYosys and formal smoke"
if done_before formal; then
  say "Already completed; local tools are under build/tools/bin/."
else
  run_logged sby-install make -C third_party/src/sby install "PREFIX=${TOOLS_PREFIX}"
  export PATH="${TOOLS_PREFIX}/bin:${PATH}"
  if command -v boolector >/dev/null 2>&1; then
    run_logged formal-smoke sby -d "${COURSE_ROOT}/build/formal/rv_pipeline" -f "${COURSE_ROOT}/shared/formal/rv_pipeline.sby"
  else
    warn "Formal smoke skipped because this distribution has no Boolector executable."
    SKIPPED+=("formal smoke; install Boolector and rerun after deleting build/setup-state/formal.done")
  fi
  mark_done formal
fi

stage "OpenROAD and SKY130 toolchain"
ORFS_ROOT="${COURSE_ROOT}/third_party/src/openroad-flow-scripts"
if done_before openroad; then
  RUN_OPENROAD=1
  say "Already completed; the locked ORFS environment will be used."
elif [[ "${COURSE_SKIP_OPENROAD:-0}" == "1" ]]; then
  warn "Skipped because COURSE_SKIP_OPENROAD=1. P1–P4 RTL still runs."
  SKIPPED+=("OpenROAD/SKY130 installation")
elif confirm "Build the full OpenROAD/SKY130 flow now? This can take hours and tens of GiB."; then
  if [[ "${ID:-}" != "ubuntu" || "${VERSION_ID:-}" != "24.04" ]]; then
    warn "This locked ORFS dependency installer is qualified here only for Ubuntu 24.04."
    warn "Re-run with COURSE_SKIP_OPENROAD=1, or use an Ubuntu 24.04 machine for the complete flow."
    exit 2
  fi
  RUN_OPENROAD=1
  say "ORFS setup.sh installs its documented native dependencies; build_openroad.sh compiles the locked tool revisions."
  if (( EUID == 0 )); then
    warn "Run this installer as a normal user with sudo; pinned ORFS setup uses SUDO_USER for submodules."
    warn "For an intentionally root-only container, rerun with --skip-openroad and use the course container flow."
    exit 2
  elif (( ${#SUDO[@]} == 0 )); then
    warn "sudo is required by the documented ORFS dependency installer."
    exit 2
  fi
  run_logged openroad-dependencies "${SUDO[@]}" "${ORFS_ROOT}/setup.sh"
  # Course patch (memory only): STUDENT_MINI_DRT_BATCH_SIZE sets the detailed-router worker batch
  # (default unchanged); the student-mini GPU/CPU flows need it to stay inside 8 GiB.
  OPENROAD_PATCH="${COURSE_ROOT}/third_party/patches/openroad-drt-batch-size.patch"
  if git -C "${ORFS_ROOT}/tools/OpenROAD" apply --check "$OPENROAD_PATCH" 2>/dev/null; then
    run_logged openroad-patch git -C "${ORFS_ROOT}/tools/OpenROAD" apply "$OPENROAD_PATCH"
  elif ! git -C "${ORFS_ROOT}/tools/OpenROAD" apply --reverse --check "$OPENROAD_PATCH" 2>/dev/null; then
    warn "Course OpenROAD patch does not apply to tools/OpenROAD; check the locked revision."
    exit 2
  fi
  run_logged openroad-build "${ORFS_ROOT}/build_openroad.sh" --local --threads "$JOBS"
  mark_done openroad
else
  warn "OpenROAD was skipped. Re-run later and answer yes, or set COURSE_SKIP_OPENROAD=0."
  SKIPPED+=("OpenROAD/SKY130 installation and PPA runs")
fi
activate_course_env

if [[ "$PHASE" == "setup" ]]; then
  write_course_env
  verify_args=(--strict --require-course-tools)
  if (( RUN_OPENROAD == 1 )); then verify_args+=(--require-openroad); fi
  run_logged final-tool-report python scripts/verify_toolchain.py "${verify_args[@]}"
  say "Tool installation completed. Next: --phase golden or --phase rtl --project p1."
  finish
  exit 0
fi

stage "P1–P4 Python golden models"
run_logged structure python scripts/lint_structure.py
mapfile -t PROJECTS < <(selected_projects)
for design in "${PROJECTS[@]}"; do run_golden "$design"; done

stage "P1–P4 Verilator/cocotb RTL"
run_profile_contracts
for design in "${PROJECTS[@]}"; do run_rtl "$design"; done

stage "Optional P1–P4 OpenROAD PPA and final report"
if (( RUN_OPENROAD == 1 )); then
  if [[ "${COURSE_RUN_PPA:-0}" == "1" ]] || confirm "Run complete SKY130 synthesis/place/route for P1–P4 now?"; then
    for design in "${PROJECTS[@]}"; do run_ppa "$design"; done
  else
    SKIPPED+=("P1–P4 OpenROAD PPA execution; tools are installed and ready")
  fi
else
  say "PPA was not attempted because OpenROAD was not installed in Stage 6."
fi
verify_args=(--strict --require-course-tools)
if (( RUN_OPENROAD == 1 )); then verify_args+=(--require-openroad); fi
run_logged final-tool-report python scripts/verify_toolchain.py "${verify_args[@]}"
write_course_env
say "Selected project golden-model and RTL runs passed: ${PROJECT}."
say "Logs: ${LOG_DIR}"
say "For a later shell: source build/course-env.sh"
say "Fast rerun: bash scripts/install_and_run_p1_p4.sh --phase rtl --project p1"

finish
